mapper.update:
UPDATE vm_arbutton_device_relation
SET enable_status = #{enableStatus}
WHERE
    button_id = #{buttonId}
  AND tenant_id = #{tenantId}
  AND industry_code = #{industryCode}
  AND accept_node = #{acceptNode}

mapper.delete:
DELETE
FROM vm_arbutton_device_relation
WHERE button_id = #{buttonId}
  AND tenant_id = #{tenantId}
  AND industry_code = #{industryCode}
  AND accept_node = #{acceptNode}

mapper.select:
SELECT COUNT(1)
FROM vm_arbutton_device_relation
WHERE button_id = #{buttonId}
  AND tenant_id = #{tenantId}
  AND industry_code = #{industryCode}
  AND accept_node = #{acceptNode}

SELECT

FROM
vm_arbutton_device_relation
WHERE
tenant_id = #{tenantId}
AND industry_code = #{industryCode}
AND accept_node = #{acceptNode}

    AND device_code = #{deviceCode}


    AND enable_status = #{enableStatus}


    AND button_id = #{buttonId}

SELECT
relation.device_code
FROM
vm_arbutton_device_relation relation
LEFT JOIN (
SELECT
d1.device_code,
MIN(d1.ID) AS min_id
FROM
vm_order_devices d1
WHERE
d1.tenant_id = #{tenantId}
AND d1.industry_code = #{industryCode}
AND d1.accept_node = #{acceptNode}
AND d1.ord_status IN (0, 1, 2)
GROUP BY
d1.device_code
) deviceOrder ON relation.device_code = deviceOrder.device_code
WHERE
relation.enable_status = #{enableStatus}
AND relation.tenant_id = #{tenantId}
AND relation.industry_code = #{industryCode}
AND relation.accept_node = #{acceptNode}

    AND relation.device_code IN (
    SELECT device_code
    FROM vm_arbutton_device_relation
    WHERE button_id = #{buttonId}
    )

GROUP BY
relation.device_code
HAVING
COUNT(*) > #{varCount}
